package calc

import (
	"bufio"
	"errors"
	"io"
	"math"
	"strconv"
)

var (
	errSyntax   = errors.New("syntax error")
	errDivZero  = errors.New("division by zero")
	errOverflow = errors.New("integer overflow")
)

// Operator codes held on the operator stack. opNeg is unary minus; opParen
// marks an open parenthesis.
const (
	opParen byte = '('
	opNeg   byte = 'n'
	opAdd   byte = '+'
	opSub   byte = '-'
	opMul   byte = '*'
	opDiv   byte = '/'
	opRem   byte = '%'
)

// Run executes the calc subcommand: each line of r is evaluated and its value,
// or "error", is written to w. Blank lines produce no output.
func Run(r io.Reader, w io.Writer) error {
	br := bufio.NewReaderSize(r, 64<<10)
	var (
		ev   evaluator
		line []byte // accumulates lines longer than the reader's buffer
		out  []byte
	)
	for {
		chunk, err := br.ReadSlice('\n')
		if err == bufio.ErrBufferFull {
			line = append(line, chunk...)
			continue
		}
		if err != nil && err != io.EOF {
			return err
		}
		if len(line) > 0 {
			line = append(line, chunk...)
			chunk = line
		}
		if n := len(chunk); n > 0 && chunk[n-1] == '\n' {
			chunk = chunk[:n-1]
		}
		if !isBlank(chunk) {
			out = out[:0]
			if v, everr := ev.eval(chunk); everr != nil {
				out = append(out, "error"...)
			} else {
				out = strconv.AppendInt(out, v, 10)
			}
			out = append(out, '\n')
			if _, werr := w.Write(out); werr != nil {
				return werr
			}
		}
		if cap(line) > 1<<20 {
			line = nil // don't pin a huge buffer after one very long line
		} else {
			line = line[:0]
		}
		if err == io.EOF {
			return nil
		}
	}
}

// Eval evaluates a single expression according to the grammar in SPEC.md.
func Eval(expr []byte) (int64, error) {
	var ev evaluator
	return ev.eval(expr)
}

func isBlank(b []byte) bool {
	for _, c := range b {
		if c != ' ' && c != '\t' {
			return false
		}
	}
	return true
}

// evaluator is an operator-precedence (shunting-yard) evaluator. It uses
// explicit stacks rather than recursion so that arbitrarily deep nesting
// cannot exhaust the goroutine stack. Its stacks are reused across calls.
type evaluator struct {
	ops  []byte
	vals []int64
}

func (e *evaluator) eval(s []byte) (int64, error) {
	e.ops = e.ops[:0]
	e.vals = e.vals[:0]
	expectOperand := true

	for i := 0; i < len(s); {
		c := s[i]
		if c == ' ' || c == '\t' {
			i++
			continue
		}
		if expectOperand {
			switch {
			case isDigit(c):
				v, n, err := parseNumber(s[i:])
				if err != nil {
					return 0, err
				}
				e.vals = append(e.vals, v)
				i += n
				expectOperand = false
				continue
			case c == '-':
				e.ops = append(e.ops, opNeg)
			case c == '(':
				e.ops = append(e.ops, opParen)
			default:
				return 0, errSyntax
			}
			i++
			continue
		}

		switch c {
		case opAdd, opSub, opMul, opDiv, opRem:
			// All binary operators are left-associative, so reduce while the
			// pending operator binds at least as tightly.
			p := precedence(c)
			for len(e.ops) > 0 {
				top := e.ops[len(e.ops)-1]
				if top == opParen || precedence(top) < p {
					break
				}
				if err := e.reduce(); err != nil {
					return 0, err
				}
			}
			e.ops = append(e.ops, c)
			expectOperand = true
		case ')':
			if err := e.reduceToParen(); err != nil {
				return 0, err
			}
		default:
			return 0, errSyntax
		}
		i++
	}

	if expectOperand {
		return 0, errSyntax
	}
	for len(e.ops) > 0 {
		if e.ops[len(e.ops)-1] == opParen {
			return 0, errSyntax // unclosed '('
		}
		if err := e.reduce(); err != nil {
			return 0, err
		}
	}
	if len(e.vals) != 1 {
		return 0, errSyntax
	}
	return e.vals[0], nil
}

// reduceToParen applies operators down to the nearest '(' and discards it.
func (e *evaluator) reduceToParen() error {
	for len(e.ops) > 0 {
		if e.ops[len(e.ops)-1] == opParen {
			e.ops = e.ops[:len(e.ops)-1]
			return nil
		}
		if err := e.reduce(); err != nil {
			return err
		}
	}
	return errSyntax // unmatched ')'
}

// reduce pops the top operator and applies it to the top of the value stack.
func (e *evaluator) reduce() error {
	op := e.ops[len(e.ops)-1]
	e.ops = e.ops[:len(e.ops)-1]

	n := len(e.vals)
	if op == opNeg {
		if n < 1 {
			return errSyntax
		}
		v := e.vals[n-1]
		if v == math.MinInt64 {
			return errOverflow
		}
		e.vals[n-1] = -v
		return nil
	}

	if n < 2 {
		return errSyntax
	}
	r, err := apply(op, e.vals[n-2], e.vals[n-1])
	if err != nil {
		return err
	}
	e.vals[n-2] = r
	e.vals = e.vals[:n-1]
	return nil
}

func precedence(op byte) int {
	switch op {
	case opAdd, opSub:
		return 1
	case opMul, opDiv, opRem:
		return 2
	case opNeg:
		return 3
	}
	return 0
}

// apply computes a op b, reporting division by zero and any result outside
// the int64 range.
func apply(op byte, a, b int64) (int64, error) {
	switch op {
	case opAdd:
		r := a + b
		if (a >= 0) == (b >= 0) && (r >= 0) != (a >= 0) {
			return 0, errOverflow
		}
		return r, nil
	case opSub:
		r := a - b
		if (a >= 0) != (b >= 0) && (r >= 0) != (a >= 0) {
			return 0, errOverflow
		}
		return r, nil
	case opMul:
		if a == 0 || b == 0 {
			return 0, nil
		}
		if (a == -1 && b == math.MinInt64) || (b == -1 && a == math.MinInt64) {
			return 0, errOverflow
		}
		r := a * b
		if r/b != a {
			return 0, errOverflow
		}
		return r, nil
	case opDiv:
		if b == 0 {
			return 0, errDivZero
		}
		if a == math.MinInt64 && b == -1 {
			return 0, errOverflow
		}
		return a / b, nil
	case opRem:
		if b == 0 {
			return 0, errDivZero
		}
		if b == -1 {
			return 0, nil // exact result is 0 even for MinInt64
		}
		return a % b, nil
	}
	panic("calc: unknown operator " + strconv.QuoteRune(rune(op)))
}

// parseNumber parses the maximal run of decimal digits at the start of s,
// returning its value and length. It fails if the literal exceeds MaxInt64.
func parseNumber(s []byte) (int64, int, error) {
	var v int64
	i := 0
	for ; i < len(s) && isDigit(s[i]); i++ {
		d := int64(s[i] - '0')
		if v > (math.MaxInt64-d)/10 {
			return 0, 0, errOverflow
		}
		v = v*10 + d
	}
	return v, i, nil
}

func isDigit(c byte) bool { return '0' <= c && c <= '9' }

package calc

import (
	"bytes"
	"strings"
	"testing"
)

func TestEval(t *testing.T) {
	tests := []struct {
		in   string
		want int64
		err  bool
	}{
		{in: "1 + 2 * 3", want: 7},
		{in: "-7 / 2", want: -3},
		{in: "-7 % 3", want: -1},
		{in: "7 % -3", want: 1},
		{in: "10 - 4 - 3", want: 3},
		{in: "100 / 10 / 5", want: 2},
		{in: "--5", want: 5},
		{in: "2 * -3", want: -6},
		{in: "-(2 + 3)", want: -5},
		{in: "-2 * 3", want: -6},
		{in: "((((7))))", want: 7},
		{in: "007", want: 7},
		{in: "9223372036854775807", want: 9223372036854775807},
		{in: "-9223372036854775807 - 1", want: -9223372036854775808},
		{in: "(-9223372036854775807 - 1) % -1", want: 0},
		{in: "-9223372036854775807-1+9223372036854775807", want: -1},
		{in: "\t1\t+ 1 ", want: 2},
		{in: "9223372036854775808", err: true},
		{in: "-9223372036854775808", err: true},
		{in: "9223372036854775807 + 1", err: true},
		{in: "(-9223372036854775807 - 1) - 1", err: true},
		{in: "(-9223372036854775807 - 1) / -1", err: true},
		{in: "(-9223372036854775807 - 1) * -1", err: true},
		{in: "-(-9223372036854775807 - 1)", err: true},
		{in: "4294967296 * 4294967296", err: true},
		{in: "3037000500 * 3037000500", err: true},
		{in: "1 / 0", err: true},
		{in: "1 % 0", err: true},
		{in: "(1 + 2", err: true},
		{in: "1 + 2)", err: true},
		{in: "()", err: true},
		{in: "1 +", err: true},
		{in: "1 2", err: true},
		{in: "+1", err: true},
		{in: "abc", err: true},
		{in: "1 + 2\r", err: true},
		{in: "(1)(2)", err: true},
		{in: "1 * / 2", err: true},
		{in: "-", err: true},
	}
	for _, tt := range tests {
		got, err := Eval([]byte(tt.in))
		if tt.err {
			if err == nil {
				t.Errorf("Eval(%q) = %d, want error", tt.in, got)
			}
			continue
		}
		if err != nil || got != tt.want {
			t.Errorf("Eval(%q) = %d, %v; want %d", tt.in, got, err, tt.want)
		}
	}
}

func TestEvalDeepNesting(t *testing.T) {
	const depth = 1_000_000
	expr := strings.Repeat("(", depth) + "1" + strings.Repeat(")", depth)
	if got, err := Eval([]byte(expr)); err != nil || got != 1 {
		t.Fatalf("deep parens = %d, %v; want 1", got, err)
	}
	expr = strings.Repeat("-", depth) + "1"
	if got, err := Eval([]byte(expr)); err != nil || got != 1 {
		t.Fatalf("deep negation = %d, %v; want 1", got, err)
	}
}

func TestRun(t *testing.T) {
	in := "1 + 2 * 3\n-7 / 2\n\n  \t\n(1 + 2\n9223372036854775807 + 1\n" +
		strings.Repeat("1+", 100_000) + "1"
	want := "7\n-3\nerror\nerror\n100001\n"
	var out bytes.Buffer
	if err := Run(strings.NewReader(in), &out); err != nil {
		t.Fatal(err)
	}
	if out.String() != want {
		t.Errorf("Run output = %q, want %q", out.String(), want)
	}
}

// Package calc implements the calc subcommand: a 64-bit signed integer
// expression evaluator, one expression per input line.
package calc

// Package lru implements the lru subcommand: an LRU cache simulator driven
// by commands read from its input.
package lru

package lru

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
	"strconv"
)

// MaxCapacity is the largest capacity accepted on the first input line.
const MaxCapacity = 1_000_000

// nilIndex marks the absence of a node in the intrusive list.
const nilIndex = -1

// node is an entry of the cache. Nodes live in a slice and link to each
// other by index, which keeps the list compact and free of per-entry
// pointers for the garbage collector to trace.
type node struct {
	key, value string
	prev, next int32
}

// Cache is a fixed-capacity LRU cache from string keys to string values.
// Every operation runs in O(1) expected time. The zero value is not usable;
// create caches with New.
type Cache struct {
	capacity int
	index    map[string]int32
	nodes    []node
	free     []int32 // indices of nodes released by Delete
	head     int32   // most recently used, or nilIndex
	tail     int32   // least recently used, or nilIndex
}

// New returns an empty cache holding at most capacity keys. It panics if
// capacity is not positive.
func New(capacity int) *Cache {
	if capacity < 1 {
		panic("lru: capacity must be positive")
	}
	hint := min(capacity, 1<<16)
	return &Cache{
		capacity: capacity,
		index:    make(map[string]int32, hint),
		nodes:    make([]node, 0, hint),
		head:     nilIndex,
		tail:     nilIndex,
	}
}

// Len reports the number of keys held.
func (c *Cache) Len() int { return len(c.index) }

// Get returns the value stored under key and marks key as the most recently
// used. The boolean reports whether the key was present.
func (c *Cache) Get(key string) (string, bool) {
	i, ok := c.index[key]
	if !ok {
		return "", false
	}
	c.moveToFront(i)
	return c.nodes[i].value, true
}

// Set stores value under key and marks key as the most recently used,
// evicting the least recently used key if the cache would exceed its
// capacity.
func (c *Cache) Set(key, value string) {
	if i, ok := c.index[key]; ok {
		c.nodes[i].value = value
		c.moveToFront(i)
		return
	}

	var i int32
	switch {
	case len(c.index) >= c.capacity:
		// Recycle the evicted node for the new entry.
		i = c.tail
		c.unlink(i)
		delete(c.index, c.nodes[i].key)
	case len(c.free) > 0:
		i = c.free[len(c.free)-1]
		c.free = c.free[:len(c.free)-1]
	default:
		i = int32(len(c.nodes))
		c.nodes = append(c.nodes, node{})
	}
	c.nodes[i] = node{key: key, value: value}
	c.index[key] = i
	c.pushFront(i)
}

// Delete removes key and reports whether it was present.
func (c *Cache) Delete(key string) bool {
	i, ok := c.index[key]
	if !ok {
		return false
	}
	c.unlink(i)
	delete(c.index, key)
	c.nodes[i] = node{} // drop string references
	c.free = append(c.free, i)
	return true
}

func (c *Cache) moveToFront(i int32) {
	if c.head == i {
		return
	}
	c.unlink(i)
	c.pushFront(i)
}

func (c *Cache) pushFront(i int32) {
	n := &c.nodes[i]
	n.prev = nilIndex
	n.next = c.head
	if c.head != nilIndex {
		c.nodes[c.head].prev = i
	} else {
		c.tail = i
	}
	c.head = i
}

func (c *Cache) unlink(i int32) {
	n := &c.nodes[i]
	if n.prev != nilIndex {
		c.nodes[n.prev].next = n.next
	} else {
		c.head = n.next
	}
	if n.next != nilIndex {
		c.nodes[n.next].prev = n.prev
	} else {
		c.tail = n.prev
	}
	n.prev, n.next = nilIndex, nilIndex
}

// Run executes the lru subcommand, reading from r and writing to w.
//
// The first line holds the cache capacity; each later line is one command
// (SET, GET, DEL or SIZE). Blank and unrecognized lines are ignored.
func Run(r io.Reader, w io.Writer) error {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 0, 64<<10), 1<<20)

	if !sc.Scan() {
		if err := sc.Err(); err != nil {
			return err
		}
		return errors.New("missing capacity line")
	}
	capacity, err := strconv.Atoi(string(bytes.TrimSpace(sc.Bytes())))
	if err != nil || capacity < 1 || capacity > MaxCapacity {
		return fmt.Errorf("invalid capacity %q: want an integer in [1, %d]", sc.Bytes(), MaxCapacity)
	}

	c := New(capacity)
	var out []byte // output of the current command, reused across commands
	for sc.Scan() {
		line := bytes.TrimSuffix(sc.Bytes(), []byte{'\r'})
		cmd, rest, _ := bytes.Cut(line, []byte{' '})
		out = out[:0]
		switch string(cmd) {
		case "SET":
			key, value, ok := bytes.Cut(rest, []byte{' '})
			if !ok {
				continue
			}
			c.Set(string(key), string(value))
			continue
		case "GET":
			if v, ok := c.Get(string(rest)); ok {
				out = append(out, v...)
			} else {
				out = append(out, "NULL"...)
			}
		case "DEL":
			if c.Delete(string(rest)) {
				out = append(out, '1')
			} else {
				out = append(out, '0')
			}
		case "SIZE":
			out = strconv.AppendInt(out, int64(c.Len()), 10)
		default:
			continue
		}
		out = append(out, '\n')
		if _, err := w.Write(out); err != nil {
			return err
		}
	}
	return sc.Err()
}

package lru

import (
	"strings"
	"testing"
)

func TestRun(t *testing.T) {
	tests := []struct {
		name, in, want string
	}{
		{
			name: "spec example",
			in:   "2\nSET a 1\nSET b 2\nGET a\nSET c 3\nGET b\nSIZE\n",
			want: "1\nNULL\n2\n",
		},
		{
			name: "overwrite refreshes recency",
			in:   "2\nSET a 1\nSET b 2\nSET a 9\nSET c 3\nGET a\nGET b\nGET c\n",
			want: "9\nNULL\n3\n",
		},
		{
			name: "delete",
			in:   "3\nSET a 1\nDEL a\nDEL a\nGET a\nSIZE\n",
			want: "1\n0\nNULL\n0\n",
		},
		{
			name: "deleted slot is reused",
			in:   "2\nSET a 1\nSET b 2\nDEL a\nSET c 3\nSET d 4\nGET b\nGET c\nGET d\nSIZE\n",
			want: "1\nNULL\n3\n4\n2\n",
		},
		{
			name: "capacity one",
			in:   "1\nSET a 1\nSET b 2\nGET a\nGET b\nSIZE",
			want: "NULL\n2\n1\n",
		},
		{
			name: "missing final newline",
			in:   "5\nSET k v\nGET k",
			want: "v\n",
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var out strings.Builder
			if err := Run(strings.NewReader(tt.in), &out); err != nil {
				t.Fatalf("Run: %v", err)
			}
			if got := out.String(); got != tt.want {
				t.Errorf("Run(%q) = %q, want %q", tt.in, got, tt.want)
			}
		})
	}
}

func TestRunInvalidCapacity(t *testing.T) {
	for _, in := range []string{"", "0\n", "1000001\n", "x\n"} {
		if err := Run(strings.NewReader(in), &strings.Builder{}); err == nil {
			t.Errorf("Run(%q): want error", in)
		}
	}
}

func TestCacheEvictsLeastRecentlyUsed(t *testing.T) {
	c := New(2)
	c.Set("a", "1")
	c.Set("b", "2")
	c.Get("a")
	c.Set("c", "3")
	if _, ok := c.Get("b"); ok {
		t.Error("b should have been evicted")
	}
	for _, k := range []string{"a", "c"} {
		if _, ok := c.Get(k); !ok {
			t.Errorf("%s should be present", k)
		}
	}
	if n := c.Len(); n != 2 {
		t.Errorf("Len = %d, want 2", n)
	}
}

// Package wordfreq implements the wordfreq subcommand: it prints the ten
// most frequent ASCII words of its input.
package wordfreq

package wordfreq

import (
	"errors"
	"fmt"
	"io"
	"slices"
)

// topN is the maximum number of words reported.
const topN = 10

// lower maps every ASCII letter to its lowercase form and every other byte
// to 0, which marks it as a word separator.
var lower = func() (t [256]byte) {
	for c := byte('a'); c <= 'z'; c++ {
		t[c] = c
		t[c-'a'+'A'] = c
	}
	return t
}()

// entry is a word together with its number of occurrences.
type entry struct {
	word  string
	count int
}

// compare orders entries by count descending, then by word ascending.
func compare(a, b entry) int {
	switch {
	case a.count > b.count:
		return -1
	case a.count < b.count:
		return 1
	case a.word < b.word:
		return -1
	case a.word > b.word:
		return 1
	}
	return 0
}

// Run executes the wordfreq subcommand, reading from r and writing to w.
func Run(r io.Reader, w io.Writer) error {
	counts, err := count(r)
	if err != nil {
		return err
	}
	for _, e := range top(counts, topN) {
		if _, err := fmt.Fprintf(w, "%d %s\n", e.count, e.word); err != nil {
			return err
		}
	}
	return nil
}

// count reads all of r and returns the number of occurrences of each word,
// folded to lowercase. A word is a maximal run of ASCII letters; every other
// byte is a separator.
//
// Counters are stored behind pointers so that incrementing a known word only
// needs a map lookup, which the compiler performs without allocating a
// string from the byte slice.
func count(r io.Reader) (map[string]*int, error) {
	counts := make(map[string]*int)
	add := func(word []byte) {
		if p, ok := counts[string(word)]; ok {
			*p++
			return
		}
		n := 1
		counts[string(word)] = &n
	}

	buf := make([]byte, 256<<10)
	var word []byte // current word; it may span several reads
	for {
		n, err := r.Read(buf)
		for _, c := range buf[:n] {
			if l := lower[c]; l != 0 {
				word = append(word, l)
			} else if len(word) > 0 {
				add(word)
				word = word[:0]
			}
		}
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return nil, err
		}
	}
	if len(word) > 0 {
		add(word)
	}
	return counts, nil
}

// top returns at most n entries of counts in ranking order.
func top(counts map[string]*int, n int) []entry {
	if n <= 0 {
		return nil
	}
	best := make([]entry, 0, n+1)
	for w, p := range counts {
		e := entry{word: w, count: *p}
		if len(best) == n && compare(e, best[n-1]) >= 0 {
			continue
		}
		i, _ := slices.BinarySearchFunc(best, e, compare)
		best = slices.Insert(best, i, e)
		if len(best) > n {
			best = best[:n]
		}
	}
	return best
}

package wordfreq

import (
	"bytes"
	"strings"
	"testing"
	"testing/iotest"
)

func TestRun(t *testing.T) {
	tests := []struct {
		name, in, want string
	}{
		{"example", "The cat and the hat.", "2 the\n1 and\n1 cat\n1 hat\n"},
		{"empty", "", ""},
		{"no words", "123 _ ' !? \xff\xfe", ""},
		{"case folding", "Hello hELLo HELLO world", "3 hello\n1 world\n"},
		{"separators", "a1b_c'd\xc3\xa9e", "1 a\n1 b\n1 c\n1 d\n1 e\n"},
		{"trailing word", "x y x", "2 x\n1 y\n"},
		{
			"top ten with ties",
			"zeta eta theta iota kappa lambda mu nu xi omicron pi rho alpha beta alpha",
			"2 alpha\n1 beta\n1 eta\n1 iota\n1 kappa\n1 lambda\n1 mu\n1 nu\n1 omicron\n1 pi\n",
		},
		{"byte order", "b B a A ab", "2 a\n2 b\n1 ab\n"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var out bytes.Buffer
			// OneByteReader forces words to span reads.
			if err := Run(iotest.OneByteReader(strings.NewReader(tt.in)), &out); err != nil {
				t.Fatal(err)
			}
			if got := out.String(); got != tt.want {
				t.Errorf("got %q, want %q", got, tt.want)
			}
		})
	}
}

func TestRunReadError(t *testing.T) {
	r := iotest.TimeoutReader(strings.NewReader("abc"))
	if err := Run(iotest.OneByteReader(r), new(bytes.Buffer)); err == nil {
		t.Fatal("expected error")
	}
}

// Command app is a suite of independent subcommands selected by the first
// argument. See SPEC.md for the behavior of each one.
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"sort"
	"strings"

	"suite/internal/calc"
	"suite/internal/lru"
	"suite/internal/wordfreq"
)

// runFunc is the entry point of a subcommand. It reads its input from r and
// writes its output to w. Implementations need not buffer w; the caller
// buffers and flushes it.
type runFunc func(r io.Reader, w io.Writer) error

var commands = map[string]runFunc{
	"calc":     calc.Run,
	"lru":      lru.Run,
	"wordfreq": wordfreq.Run,
}

func main() {
	os.Exit(run(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

func run(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
	if len(args) < 1 {
		fmt.Fprintf(stderr, "usage: app <%s>\n", strings.Join(names(), "|"))
		return 2
	}
	cmd, ok := commands[args[0]]
	if !ok {
		fmt.Fprintf(stderr, "app: unknown subcommand %q (want one of: %s)\n", args[0], strings.Join(names(), ", "))
		return 2
	}

	out := bufio.NewWriterSize(stdout, 64<<10)
	err := cmd(stdin, out)
	if ferr := out.Flush(); err == nil {
		err = ferr
	}
	if err != nil {
		fmt.Fprintf(stderr, "app %s: %v\n", args[0], err)
		return 1
	}
	return 0
}

func names() []string {
	ns := make([]string, 0, len(commands))
	for n := range commands {
		ns = append(ns, n)
	}
	sort.Strings(ns)
	return ns
}
